$ErrorActionPreference='Stop';$root=Split-Path -Parent (Split-Path -Parent $PSCommandPath);$cal=Join-Path $root 'calibration';$fixture=Join-Path $root 'fixture';$cases=@(@('CAL01','S01','PASS'),@('CAL02','S01','PASS'),@('CAL03','S01','FAIL'),@('CAL04','S01','FAIL'),@('CAL05','S01','PASS'),@('CAL06','S02','FAIL'),@('CAL07','S02','FAIL'),@('CAL08','S02','PASS'),@('CAL09','S02','FAIL'),@('CAL10','S01','FAIL'));$out=@();$port=58000
foreach($case in $cases){$id,$task,$expect=$case;$path=Join-Path $cal $id;if(Test-Path $path){Remove-Item $path -Recurse -Force};Copy-Item $fixture $path -Recurse;Copy-Item (Join-Path $cal "correct-$($task.ToLower()).ts") (Join-Path $path 'src/server.ts');if($id-eq'CAL03'){(Get-Content (Join-Path $path 'src/server.ts')-Raw).Replace('count(*)::int','count(*)').Replace('coalesce(sum(quantity),0)::int','coalesce(sum(quantity),0)')|Set-Content (Join-Path $path 'src/server.ts')}if($id-eq'CAL04'){(Get-Content (Join-Path $path 'src/server.ts')-Raw).Replace('coalesce(sum(quantity),0)::int','sum(quantity)::int')|Set-Content (Join-Path $path 'src/server.ts')}if($id-eq'CAL06'){(Get-Content (Join-Path $path 'src/server.ts')-Raw).Replace('for update','').Replace('on conflict (request_id) do nothing returning request_id','on conflict (request_id) do update set quantity=excluded.quantity returning request_id')|Set-Content (Join-Path $path 'src/server.ts')}if($id-in@('CAL07','CAL09')){(Get-Content (Join-Path $path 'src/server.ts')-Raw).Replace('for update','').Replace('quantity=quantity-$1','quantity=greatest(quantity-$1,0)')|Set-Content (Join-Path $path 'src/server.ts')}if($id-eq'CAL10'){(Get-Content (Join-Path $path 'src/server.ts')-Raw).Replace("app.listen(Number(process.env.PORT??3000));","throw new Error('missing published SQL asset');")|Set-Content (Join-Path $path 'src/server.ts')};$result=Join-Path $cal "$id-result.json";& $PSScriptRoot\Evaluate.ps1 -Task $task -CandidatePath $path -PostgresPort $port -ApplicationPort ($port+100) -OutputPath $result 2>&1|Tee-Object (Join-Path $cal "$id.log");$actual=(Get-Content $result -Raw|ConvertFrom-Json).primary;$out+=[ordered]@{id=$id;expected=$expect;actual=$actual;matchesExpected=($expect-eq$actual)};$port+=2};$summary=[ordered]@{result=if($out.matchesExpected-notcontains$false){'PASS'}else{'FAIL'};cases=$out};$summary|ConvertTo-Json -Depth 5|Set-Content (Join-Path $cal 'CALIBRATION-SUMMARY.json');if($summary.result-ne'PASS'){exit 1}
